// Secure application with proper error handling and input validation
const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const hpp = require('hpp');

const app = express();

// Security middleware
app.use(helmet()); // Set security headers
app.use(hpp()); // Prevent HTTP Parameter Pollution

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again after 15 minutes',
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiter to all requests
app.use(limiter);

// Enhanced logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// Input validation middleware for user ID
const validateUserId = (req, res, next) => {
  const userId = req.query.id;

  // Check if ID parameter exists
  if (userId === undefined) {
    return res.status(400).json({
      error: 'User ID is required',
      message: 'Please provide an id parameter'
    });
  }

  // Validate that ID is a positive integer
  const idNum = parseInt(userId, 10);
  if (isNaN(idNum) || idNum <= 0 || !Number.isInteger(idNum)) {
    return res.status(400).json({
      error: 'Invalid user ID',
      message: 'User ID must be a positive integer'
    });
  }

  // Store validated ID in request object
  req.validatedUserId = idNum;
  next();
};

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Uncaught error:', err);
  res.status(500).json({
    error: 'Internal server error',
    message: 'An unexpected error occurred'
  });
});

// Enhanced health check with error handling
app.get('/health', (req, res) => {
  try {
    // Simulate health checks
    const healthChecks = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage()
    };

    res.status(200).json(healthChecks);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(503).json({
      error: 'Health check failed',
      message: 'Service is currently unavailable'
    });
  }
});

// Users endpoint with input validation
app.get('/users', validateUserId, (req, res) => {
  try {
    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter users by ID if provided
    if (req.validatedUserId) {
      const user = mockUsers.find(u => u.id === req.validatedUserId);

      if (!user) {
        return res.status(404).json({
          error: 'User not found',
          message: `User with ID ${req.validatedUserId} does not exist`
        });
      }

      return res.status(200).json(user);
    }

    // Return all users if no ID specified
    res.status(200).json(mockUsers);
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      error: 'Failed to retrieve users',
      message: 'An error occurred while processing your request'
    });
  }
});

// Handle 404 for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
    message: `The requested endpoint ${req.method} ${req.path} does not exist`
  });
});

// Graceful shutdown handling
const server = app.listen(3000, () => {
  console.log('Server running on port 3000');
});

// Handle unexpected errors
process.on('unhandledRejection', (err) => {
  console.error('Unhandled Promise Rejection:', err);
  server.close(() => process.exit(1));
});

process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  server.close(() => process.exit(1));
});

module.exports = app;

