const { body, validationResult } = require('express-validator');

// Reusable validation chain for user input
const validateUserInput = [
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters'),
  body('email')
    .isEmail()
    .normalizeEmail()
    .withMessage('Must be a valid email address'),

  // Validation middleware to check for errors
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        errors: errors.array().map(err => ({
          field: err.param,
          message: err.msg
        })) 
      });
    }
    next();
  }
];

module.exports = {
  validateUserInput
};

/**
 * Centralized error handling middleware
 * Follows security best practices for error disclosure
 */

// Error handling middleware
const errorHandler = (err, req, res, next) => {
  // Log error details (in production, use a proper logging service)
  console.error('Error details:', {\n    message: err.message,\n    stack: err.stack,\n    path: req.path,\n    method: req.method,\n    ip: req.ip\n  });

  // Determine status code
  const statusCode = err.statusCode || 500;

  // Security: Only include error details in development
  const response = {\n    success: false,\n    message: statusCode === 500 ? 'Internal server error' : err.message,\n  };

  // Include stack only in development
  if (process.env.NODE_ENV === 'development' && statusCode === 500) {\n    response.stack = err.stack;\n  }

  res.status(statusCode).json(response);
};

// Not found handler
const notFound = (req, res, next) => {\n  const error = new Error(`Route ${req.originalUrl} not found`);\n  error.statusCode = 404;\n  next(error);\n};

module.exports = {\n  errorHandler,\n  notFound\n};

/**
 * Security utilities for input sanitization
 */
const DOMPurify = require('dompurify');
const { JSDOM } = require('jsdom');

// Setup DOMPurify with JSDOM
const window = new JSDOM('').window;
const purify = DOMPurify(window);

/**
 * Sanitize HTML input to prevent XSS
 */
const sanitizeHTML = (html) => {\n  return purify.sanitize(html, {\n    ALLOWED_TAGS: ['p', 'br', 'strong', 'em', 'ul', 'ol', 'li'],\n    ALLOWED_ATTR: []\n  });\n};

/**
 * Sanitize text input
 */
const sanitizeText = (text) => {\n  if (typeof text !== 'string') return text;\n  
  // Remove control characters and trim
  return text\n    .replace(/[\x00-\x1F\x7F]/g, '')\n    .trim();\n};

module.exports = {\n  sanitizeHTML,\n  sanitizeText\n};

