// Security middleware
app.use(helmet()); // Sets various HTTP headers for security

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

app.use(limiter);

// Request size limiting
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation middleware
const validateIdParam = (req, res, next) => {
  const { id } = req.params;
  if (id !== undefined) {
    const idNum = parseInt(id, 10);
    if (isNaN(idNum) || idNum <= 0) {
      return res.status(400).json({
        error: 'Invalid ID parameter. Must be a positive integer.',
        timestamp: new Date().toISOString()
      });
    }
    req.params.id = idNum; // Store the parsed number
  }
  next();
};

// Health endpoint with error handling
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Health check failed',
      timestamp: new Date().toISOString() 
    });
  }
});

// Users endpoint
app.get('/users', (req, res) => {
  try {
    // Simulated database response
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Optional: Add query parameter validation
    const { limit, offset } = req.query;

    if (limit !== undefined) {
      const limitNum = parseInt(limit, 10);
      if (isNaN(limitNum) || limitNum <= 0 || limitNum > 100) {
        return res.status(400).json({
          error: 'Invalid limit parameter. Must be a positive integer between 1 and 100.',
          timestamp: new Date().toISOString()
      });
      }
    }

    if (offset !== undefined) {
      const offsetNum = parseInt(offset, 10);
      if (isNaN(offsetNum) || offsetNum < 0) {
        return res.status(400).json({
          error: 'Invalid offset parameter. Must be a non-negative integer.',
          timestamp: new Date().toISOString()
      });
      }
    }

    res.json(users);
  } catch (error) {
    console.error('Error in /users endpoint:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'An unexpected error occurred',
      timestamp: new Date().toISOString() 
    });
  }
});

// User by ID endpoint (example of using validation middleware)
app.get('/users/:id', validateIdParam, (req, res) => {
  try {
    const { id } = req.params;

    // Simulated database lookup
    const user = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ].find(u => u.id === id);

    if (!user) {
      return res.status(404).json({
        error: 'User not found',
        timestamp: new Date().toISOString()
      });
    }

    res.json(user);
  } catch (error) {
    console.error(`Error retrieving user ${req.params.id}:`, error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'An unexpected error occurred',
      timestamp: new Date().toISOString() 
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
    path: req.path,
    timestamp: new Date().toISOString()
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Uncaught error:', error);

  // Distinguish between operational and programmer errors
  if (error.statusCode) {
    res.status(error.statusCode).json({
      error: error.message,
      timestamp: new Date().toISOString()
    });
  } else {
    res.status(500).json({
      error: 'Internal server error',
      message: 'An unexpected error occurred',
      timestamp: new Date().toISOString()
    });
  }
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

