const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const cors = require('cors');
require('dotenv').config();

const app = express();

// Security middleware
app.use(helmet()); // Security headers
app.use(helmet.hidePoweredBy()); // Hide Express server information

// CORS configuration - restrict to known origins in production
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  optionsSuccessStatus: 200,
};
app.use(cors(corsOptions));

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

// Apply rate limiter to all requests
app.use(limiter);

// Request parsing with size limits to prevent abuse
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input sanitization middleware
const sanitizeInput = (req, res, next) => {
  // Sanitize query parameters
  if (req.query) {
    Object.keys(req.query).forEach(key => {
      if (typeof req.query[key] === 'string') {
        req.query[key] = req.query[key].trim();
      }
    });
  }

  // Sanitize URL parameters
  if (req.params) {
    Object.keys(req.params).forEach(key => {
      if (typeof req.params[key] === 'string') {
        req.params[key] = req.params[key].trim();
      }
    });
  }
  next();
};

app.use(sanitizeInput);

// Logging middleware
const logger = (req, res, next) => {
  const { method, originalUrl, ip } = req;
  const userAgent = req.get('User-Agent') || '';

  console.log({
    timestamp: new Date().toISOString(),
    method,
    path: originalUrl,
    ip: ip.replace(/^.*:/, ''), // Remove IPv6 prefix if present
    userAgent: userAgent.substring(0, 200), // Truncate long user agents
    queryParams: req.query
  });

  next();
};

// Only enable logging in non-production environments or when explicitly enabled
if (process.env.NODE_ENV !== 'production' || process.env.ENABLE_LOGGING === 'true') {
  app.use(logger);
}

// Health check endpoint with proper error handling
app.get('/health', (req, res) => {
  try {
    // Validate input parameters
    const requiredCheck = req.query.check;

    // If specific checks are requested, validate them
    if (requiredCheck) {
      const validChecks = ['database', 'cache', 'storage'];
      const checks = Array.isArray(requiredCheck) ? requiredCheck : [requiredCheck];

      for (const check of checks) {
        if (!validChecks.includes(check)) {
          return res.status(400).json({
            error: 'Invalid health check parameter',
            validOptions: validChecks
          });
        }
      }
    }

    const healthStatus = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      nodeEnv: process.env.NODE_ENV || 'development'
    };

    // Never expose service credentials in health checks
    if (process.env.NODE_ENV === 'production') {
      delete healthStatus.environment; // Don't expose environment details in production
    }

    res.json(healthStatus);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      error: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

// Users endpoint with proper validation and security
app.get('/users', (req, res) => {
  try {
    // Input validation
    let page = 1;
    let limit = 10;

    // Validate and sanitize pagination parameters
    if (req.query.page) {
      page = parseInt(req.query.page, 10);
      if (isNaN(page) || page < 1) {
        return res.status(400).json({
          error: 'Page parameter must be a positive integer'
        });
      }
    }

    if (req.query.limit) {
      limit = parseInt(req.query.limit, 10);
      if (isNaN(limit) || limit < 1 || limit > 100) { // Enforce reasonable limits
        return res.status(400).json({
          error: 'Limit parameter must be between 1 and 100'
        });
      }
    }

    // Filter users based on query parameters
    let filteredUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply search filtering
    if (req.query.search) {
      const searchTerm = req.query.search.toString().toLowerCase();
      filteredUsers = filteredUsers.filter(user => 
        user.name.toLowerCase().includes(searchTerm) ||
        user.email.toLowerCase().includes(searchTerm)
      );
    }

    // Mock pagination
    const startIndex = (page - 1) * limit;
    const endIndex = startIndex + limit;
    const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

    // Never expose internal IDs or sensitive data
    res.json({
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: filteredUsers.length,
        pages: Math.ceil(filteredUsers.length / limit),
        hasMore: endIndex < filteredUsers.length
      },
      timestamp: new Date().toISOString()
    });

  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      error: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
    path: req.originalUrl,
    timestamp: new Date().toISOString()
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Uncaught error:', error);

  // Don't expose stack traces in production
  const errorResponse = {
    error: 'Internal server error',
    timestamp: new Date().toISOString()
  };

  if (process.env.NODE_ENV !== 'production') {
    errorResponse.stack = error.stack;
  }

  res.status(500).json(errorResponse);
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);

  // Security warning if running in development mode on a public interface
  if (process.env.NODE_ENV !== 'production') {
    console.warn('⚠️  Warning: Running in development mode - ensure this is not exposed to public internet');
  }
});

module.exports = app;

