const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

const app = express();

// Security middleware
app.use(helmet()); // Sets various HTTP headers for security

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  }
});
app.use(limiter);

// CORS configuration (restrict to known origins in production)
const corsOptions = {
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://your-trusted-domain.com'] 
    : '*', // Only for development
  optionsSuccessStatus: 200
};
app.use(cors(corsOptions));

// Body parsing with size limits
app.use(express.json({ 
  limit: '10kb', 
  verify: (req, res, buf) => {
    try {
      JSON.parse(buf);
    } catch (e) {
      res.status(400).json({ error: 'Invalid JSON format' });
      throw new Error('Invalid JSON');
    }
  }
}));

// Request size limiting
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// Input validation middleware
const validateIdParam = (req, res, next) => {
  const id = req.params.id;
  if (id && isNaN(parseInt(id))) {
    return res.status(400).json({ 
      error: 'Invalid ID format', 
      message: 'ID must be a valid number' 
    });
  }
  next();
};

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      version: process.env.npm_package_version || '1.0.0'
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      error: 'Health check failed',
      timestamp: new Date().toISOString()
    });
  }
});

// Users endpoint with potential for ID parameter
app.get('/users', validateIdParam, (req, res) => {
  try {
    // Validate query parameters if present
    const { limit, offset } = req.query;

    if (limit && (isNaN(parseInt(limit)) || parseInt(limit) > 100)) {
      return res.status(400).json({
        error: 'Invalid limit parameter',
        message: 'Limit must be a number and cannot exceed 100'
      });
    }

    if (offset && isNaN(parseInt(offset))) {
      return res.status(400).json({
        error: 'Invalid offset parameter',
        message: 'Offset must be a number'
      });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json(users);
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'Failed to retrieve users'
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
    message: `The route ${req.method} ${req.originalUrl} does not exist`
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Safely extract error message without leaking internal details
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error'
    : error.message || 'Internal server error';

  res.status(500).json({
    error: 'Internal server error',
    message: message,
    timestamp: new Date().toISOString()
  });
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  if (process.env.NODE_ENV !== 'production') {
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  }
});

module.exports = app;

