const helmet = require('helmet');
const xss = require('xss-clean');
const cors = require('cors');

const app = express();

// Security middleware
app.use(helmet()); // Set security headers
class HttpError extends Error {
  constructor(message, statusCode = 500) {
    super(message);
    this.statusCode = statusCode;
    this.name = 'HttpError';
  }
}

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

app.use('/api/', limiter);

// Enable CORS with options (security)
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
}));

// Data sanitization against XSS
class ValidationError extends HttpError {
  constructor(message, field = null) {
    super(message, 400);
    this.field = field;
    this.name = 'ValidationError';
  }
}

// Enhanced error handling middleware
app.use(xss());

// Parse JSON bodies
app.use(express.json({
  limit: '10kb' // Limit request body size
}));

// Request logging (simple version)
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path}`);
  next();
});

// Health check endpoint with proper error handling
app.get('/health', (req, res, next) => {
  try {
    // Validate query parameters if any
    const allowedFields = ['format', 'detailed'];
    const queryParams = Object.keys(req.query);

    for (const param of queryParams) {
      if (!allowedFields.includes(param)) {
        throw new ValidationError(`Query parameter '${param}' is not allowed`, param);
      }
    }

    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    };

    // Optional detailed response
    if (req.query.detailed === 'true') {
      healthData.nodeVersion = process.version;
      healthData.memoryUsage = process.memoryUsage();
    }

    res.json(healthData);
  } catch (error) {
    next(error);
  }
});

// Users endpoint with input validation
app.get('/users', (req, res, next) => {
  try {
    // Validate and sanitize query parameters
    let page = 1;
    let limit = 10;

    if (req.query.page) {
      page = parseInt(req.query.page, 10);
      if (isNaN(page) || page < 1) {
        throw new ValidationError('Page must be a positive integer', 'page');
      }
    }

    if (req.query.limit) {
      limit = parseInt(req.query.limit, 10);
      if (isNaN(limit) || limit < 1 || limit > 100) {
        throw new ValidationError('Limit must be a positive integer between 1 and 100', 'limit');
      }
    }

    // Simulated user data (in real app, this would come from a database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Simple pagination
    const startIndex = (page - 1) * limit;
    const endIndex = page * limit;
    const paginatedUsers = users.slice(startIndex, endIndex);

    res.json({
      users: paginatedUsers,
      pagination: {
        currentPage: page,
        totalPages: Math.ceil(users.length / limit),
        totalUsers: users.length,
        hasNext: endIndex < users.length,
        hasPrev: startIndex > 0
      }
    });

  } catch (error) {
    next(error);
  }
});

// 404 handler for undefined routes
app.use('*', (req, res, next) => {
  next(new HttpError(`Cannot ${req.method} ${req.path}`, 404));
});

// Global error handling middleware
app.use((error, req, res, next) => {
  // Log error (in production, use a proper logging library)
  console.error('Error:', error);

  // Set default error values
  const statusCode = error.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' && statusCode === 500
    ? 'Internal Server Error'
    : error.message;

  // Send response
  res.status(statusCode).json({
    status: 'error',
    message: message,
    // Include validation field error only in development
    ...(error.field && process.env.NODE_ENV !== 'production' && { field: error.field }),
    // Include stack trace only in development
    ...(process.env.NODE_ENV === 'development' && { stack: error.stack })
  });
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = app;

