const express = require('express');
const app = express();

// Custom error classes

class HttpError extends Error {
  constructor(message, statusCode = 500) {
    super(message);
    this.statusCode = statusCode;
    this.name = 'HttpError';
  }
}

class ValidationError extends HttpError {
  constructor(message, field = null) {
    super(message, 400);
    this.field = field;
    this.name = 'ValidationError';
  }
}

// Set security headers manually (basic helmet functionality)
app.use((req, res, next) => {
  // Security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Referrer-Policy', 'no-referrer');

  // Limit request body size
  if (req.method === 'POST' || req.method === 'PUT' || req.method === 'PATCH') {
    let body = '';
    req.on('data', chunk => {
      body += chunk.toString();
      if (body.length > 10240) { // 10KB limit
        res.status(413).json({
          status: 'error',
          message: 'Payload too large'
        });
        req.destroy(); // Close connection
      }
    });

    req.on('end', () => {
      if (body) {
        try {
          req.body = JSON.parse(body);
        } catch (e) {
          return res.status(400).json({
            status: 'error',
            message: 'Invalid JSON'
          });
        }
      }
      next();
    });
  } else {
    next();
  }
});

// Request logging
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path}`);
  next();
});

// Health check endpoint with input validation
app.get('/health', (req, res, next) => {
  try {
    // Validate query parameters
    const allowedFields = ['format', 'detailed'];
    const queryParams = Object.keys(req.query);

    for (const param of queryParams) {
      if (!allowedFields.includes(param)) {
        throw new ValidationError(`Query parameter '${param}' is not allowed`, param);
      }
    }

    // Sanitize response data
    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: Math.floor(process.uptime()),
    };

    // Optional detailed response
    if (req.query.detailed === 'true') {
      healthData.nodeVersion = process.version;
      // Don't expose sensitive memory information in production
      if (process.env.NODE_ENV !== 'production') {
        healthData.memoryUsage = process.memoryUsage();
      }
    }

    res.json(healthData);
  } catch (error) {
    next(error);
  }
});

// Users endpoint with input validation and pagination
app.get('/users', (req, res, next) => {
  try {
    // Input validation and sanitization
    let page = 1;
    let limit = 10;

    // Validate and sanitize page parameter
    if (req.query.page) {
      page = parseInt(req.query.page, 10);
      if (isNaN(page) || page < 1) {
        throw new ValidationError('Page must be a positive integer', 'page');
      }
    }

    // Validate and sanitize limit parameter
    if (req.query.limit) {
      limit = parseInt(req.query.limit, 10);
      if (isNaN(limit) || limit < 1 || limit > 100) {
        throw new ValidationError('Limit must be a positive integer between 1 and 100', 'limit');
      }
    }

    // Simulated user data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const startIndex = (page - 1) * limit;
    const endIndex = page * limit;
    const paginatedUsers = users.slice(startIndex, endIndex);

    // Return structured response with pagination metadata
    res.json({
      users: paginatedUsers,
      pagination: {
        currentPage: page,
        totalPages: Math.ceil(users.length / limit),
        totalUsers: users.length,
        hasNext: endIndex < users.length,
        hasPrev: startIndex > 0
      }
    });

  } catch (error) {
    next(error);
  }
});

// 404 handler for undefined routes
app.use('*', (req, res, next) => {
  next(new HttpError(`Cannot ${req.method} ${req.path}`, 404));
});

// Global error handling middleware
app.use((error, req, res, next) => {
  // Log error
  console.error('Error:', error);

  // Set default error values
  const statusCode = error.statusCode || 500;
  // Don't expose detailed error messages in production
  const message = process.env.NODE_ENV === 'production' && statusCode === 500
    ? 'Internal Server Error'
    : error.message;

  // Send response
  res.status(statusCode).json({
    status: 'error',
    message: message,
    // Include additional information only in development
    ...(process.env.NODE_ENV === 'development' && {
      ...(error.field && { field: error.field }),
      stack: error.stack
    })
  });
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = app;

