      data: {
        users,
        pagination: {
          currentPage: page,
          totalPages: Math.ceil(users.length / limit),
          totalUsers: users.length,
          hasNext: page < Math.ceil(users.length / limit),
          hasPrev: page > 1
        }
      }
    });
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Failed to retrieve users' 
    });
  }
});

