const express = require('express');
const app = express();

// Prevent Express from revealing the server is powered by Express
app.set('x-powered-by', false);

// Basic rate limiting middleware
const requestCounts = new Map();
const WINDOW_MS = 15 * 60 * 1000; // 15 minutes
const MAX_REQUESTS = 100; // Max requests per window

const rateLimitMiddleware = (req, res, next) => {
  const ip = req.ip;
  const now = Date.now();

  // Clean up old requests
  for (const [requestIp, requestTime] of requestCounts) {
    if (now - requestTime > WINDOW_MS) {
      requestCounts.delete(requestIp);
    }
  }

  // Check if IP has exceeded limit
  if (requestCounts.has(ip)) {
    const count = requestCounts.get(ip);
    if (count >= MAX_REQUESTS) {
      return res.status(429).json({ 
        status: 'error', 
        message: 'Too many requests from this IP, please try again later.' 
      });
    }
    requestCounts.set(ip, count + 1);
  } else {
    requestCounts.set(ip, 1);
  }

  next();
};

// Apply rate limiter to all requests
app.use(rateLimitMiddleware);

// Set up JSON parsing middleware with size limits
app.use(express.json({
  limit: '10kb' // Limit request body size
}));

